num = int(input("Enter a number: "))

i = 1
div = 0

while i <= num:
    if num % i == 0:
        div = div + 1
    i = i + 1

if div == 2:
    print(num, "is a Prime Number")
elif num == 1:
    print("1 is neither a Prime nor a Composite Number")
else:
    print(num, "is not a Prime Number")

